   SET enum_values = f.enum_values || '[{"value":"noch_nicht_erreicht","label_de":"Phase noch nicht erreicht (Bewertung erst nach Abschluss der Phase)","label_en":"Phase not reached yet (assessed once the phase is completed)","order_index":5,"regulation_reference":"§2.1 Phasenziele"}]'::jsonb
