-- M8203-18 pz_67_projektstopp_risikoanalyse (optional, section B)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'pz_67_projektstopp_risikoanalyse', 'Projektstopp-Prüfung mit Risikoanalyse durchgeführt (Phasenziele § 6.7 Projektabschluss nicht oder nur unvollständig erreicht)', 'Projektstopp review with risk analysis carried out (phase goals of § 6.7 project close-out not or only incompletely met)', 'boolean', NULL, false, '§3',
       '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Pflicht über REQ-14-2, sobald ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ ist; „Erreicht“, „Nicht zutreffend“ und „Phase noch nicht erreicht“ lösen die Prüfung nicht aus. Ja = die Prüfung ist durchgeführt und die Risikoanalyse (ob und wie das Projekt fortgeführt wird) dokumentiert; das Ergebnis gehört in „Projektstopp erforderlich“ (M8203-24).
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Required through REQ-14-2 as soon as a phase goal of this sheet is "not met" or "partially met"; "met", "not applicable" and "phase not reached yet" do not trigger it. Yes = the review is done and the risk analysis (whether and how the project continues) is documented; its result belongs in "Projektstopp required" (M8203-24).',
       'imported_unverified', 'Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.', 'DWA-M 820-3 §3 Z.307 (PDF S. 12)', NULL, NULL, NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(f3.order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE s.code = 'DWA-M-820-3' AND w.code = 'M8203-18'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'pz_67_projektstopp_risikoanalyse');

-- M8203-02 kleiner_kommunaler_betrieb (REQUIRED, section C)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'kleiner_kommunaler_betrieb', 'Auftraggeber ist ein kleinerer kommunaler Betrieb (§ 3: Zweistufigkeit erforderlich)', 'The client is a smaller municipal operator (§ 3: two-stage approach required)', 'boolean', NULL, true, '§3',
       '§ 3 (PDF S. 12): „Kleinere kommunale Betriebe haben die Möglichkeit, sich durch externe Fachexpertise unterstützen zu lassen. Hier ist die Zweistufigkeit erforderlich; d. h. zunächst eine Gesamtsystembetrachtung, inklusive Abwägung der Wirtschaftlichkeit, zu erstellen und erst dann Einzelprojekte zu definieren, die den langfristigen Bedarf auch wirklich decken.“ Ja = die Frage „Zweistufiger Ansatz angewandt“ wird gestellt und von REQ-05 (Warnung) geprüft. Nein (z. B. privater Auftraggeber, größerer Betrieb) = die Pflicht gilt nicht, die Frage ist ausgeblendet. Pflichtangabe.
[EN] § 3: "Smaller municipal operators may draw on external expertise. Here the two-stage approach is required …" Yes = the question "two-stage approach applied" is asked and checked by REQ-05 (warning). No (e.g. a private client, a larger operator) = the duty does not apply and the question is hidden. Required.',
       'imported_unverified', 'Kleinere kommunale Betriebe haben die Möglichkeit, sich durch externe Fachexpertise unterstützen zu lassen. Hier ist die Zweistufigkeit erforderlich; d. h. zunächst eine Gesamtsystembetrachtung, inklusive Abwägung der Wirtschaftlichkeit, zu erstellen und erst dann Einzelprojekte zu definieren, die den langfristigen Bedarf auch wirklich decken.', 'DWA-M 820-3 §3 Z.305 (PDF S. 12)', NULL, NULL, NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(f3.order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE s.code = 'DWA-M-820-3' AND w.code = 'M8203-02'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'kleiner_kommunaler_betrieb');

-- M8203-19 digitale_methoden_bim_angewendet (REQUIRED, section C)
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, consumer_worksheets, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'C'), 'digitale_methoden_bim_angewendet', 'Das Projekt wird mit digitaler Planung nach der BIM-Methodik abgewickelt', 'The project is run with digital planning using the BIM method', 'boolean', NULL, true, '§7.2.1; §7.5.2',
       '§ 7.2.1 (PDF S. 21): „Die digitale Planung, hier insbesondere die BIM-Methodik, kristallisiert sich mehr und mehr als Arbeitsinstrument und Methode heraus. Die digitale Kommunikation von Projektmodellen sowie die Integration der Planungsleistungen anderer Planungsgewerke sind in Vorbereitung oder bereits teilweise in der Umsetzung.“ § 7.5.2 (PDF S. 23): „Unter Projektkommunikation wird der Einsatz von Kommunikationsplattformen verstanden. Beim Einsatz der BIM-Planung stehen dafür Werkzeuge bereit und werden eingesetzt.“ § 7.1 (PDF S. 21): „Details zur BIM-Planung werden in einer DWA-Arbeitsgruppe für die Wasser- und Abwasserwirtschaft erarbeitet und in der Merkblattreihe DWA-M 860 dokumentiert.“ Ja = die BIM-Ziele gelten: § 7.2.2 (REQ-25), § 7.2.3 (REQ-26) auf diesem Blatt, § 7.5.2 (REQ-29) auf M8203-21. Nein = diese Fragen sind ausgeblendet und die Prüfungen nicht erforderlich. Bestandsdaten (§ 7.3), Datenrechte (§ 7.4) und Bürgerinformation (§ 7.5.3) gelten unabhängig davon. Pflichtangabe; ohne Antwort warten die drei Prüfungen.
[EN] § 7.2.1: "Digital planning, here in particular the BIM method, is increasingly emerging as a working tool and method. The digital communication of project models and the integration of the planning services of other trades are in preparation or already partly in practice." § 7.5.2: "… Where BIM planning is used, tools are available for this and are used." § 7.1: BIM details are documented in the DWA-M 860 series. Yes = the BIM goals apply: § 7.2.2 (REQ-25), § 7.2.3 (REQ-26) on this sheet, § 7.5.2 (REQ-29) on M8203-21. No = those questions are hidden and the checks not required. Existing-asset data (§ 7.3), data rights (§ 7.4) and public information (§ 7.5.3) apply regardless. Required; without an answer the three checks wait.',
       'imported_unverified', 'Die digitale Planung, hier insbesondere die BIM-Methodik, kristallisiert sich mehr und mehr als Arbeitsinstrument und Methode heraus. Die digitale Kommunikation von Projektmodellen sowie die Integration der Planungsleistungen anderer Planungsgewerke sind in Vorbereitung oder bereits teilweise in der Umsetzung. — Unter Projektkommunikation wird der Einsatz von Kommunikationsplattformen verstanden. Beim Einsatz der BIM-Planung stehen dafür Werkzeuge bereit und werden eingesetzt.', 'DWA-M 820-3 §7.2.1 Z.583 (PDF S. 21) + §7.5.2 Z.659 (PDF S. 23) + §7.1 Z.573 (PDF S. 21)', NULL, NULL, NULL, NULL, NULL, ARRAY['M8203-21']::text[], (SELECT COALESCE(MAX(f3.order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE s.code = 'DWA-M-820-3' AND w.code = 'M8203-19'
   AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'digitale_methoden_bim_angewendet');

-- 3. gate edits (md5 guard on the 2026-10-05 live text; a changed live text makes the UPDATE a no-op)
-- REQ-06 M8203-04
UPDATE compliance_requirements cr
   SET condition = 'IF project_type IN {''gesamtsystem'', ''both''} THEN ((pz_52_1_status == "erreicht" OR pz_52_1_status == "teilweise_erreicht" OR pz_52_1_status == "nicht_zutreffend" OR pz_52_1_status == "noch_nicht_erreicht") AND (pz_52_2_status == "erreicht" OR pz_52_2_status == "teilweise_erreicht" OR pz_52_2_status == "nicht_zutreffend" OR pz_52_2_status == "noch_nicht_erreicht") AND (pz_52_3_status == "erreicht" OR pz_52_3_status == "teilweise_erreicht" OR pz_52_3_status == "nicht_zutreffend" OR pz_52_3_status == "noch_nicht_erreicht") AND (pz_52_4_status == "erreicht" OR pz_52_4_status == "teilweise_erreicht" OR pz_52_4_status == "nicht_zutreffend" OR pz_52_4_status == "noch_nicht_erreicht") AND (pz_52_5_status == "erreicht" OR pz_52_5_status == "teilweise_erreicht" OR pz_52_5_status == "nicht_zutreffend" OR pz_52_5_status == "noch_nicht_erreicht"))',
       description = 'Alle Phasenziele von § 5.2 Bedarfsplanung Konzept (Status je Ziel auf diesem Blatt). Bestanden: Erreicht, Teilweise erreicht, Nicht zutreffend oder Phase noch nicht erreicht; „Nicht erreicht“ blockiert. Gilt nur für den Pfad „Gesamtsystem“ (Projekttyp Gesamtsystem oder Beides) — L321 (PDF S. 13): „Die Aufteilung in „Konzept für das Gesamtsystem“ und „Projekte“ ist dabei eine elementare Grundlage.“; ohne Projekttyp (M8203-01) wartet die Prüfung. „Phase noch nicht erreicht“: Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“ (§ 2.1, PDF S. 10); die Bewertung liegt beim Projektteam (L202, PDF S. 9: „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“). „Teilweise erreicht“ besteht hier, löst aber die Projektstopp-Prüfung REQ-06-2 aus (§ 3, PDF S. 12: „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich.“).
[EN] All phase goals of § 5.2 needs planning (concept) (status per goal on this sheet). Pass: met, partially met, not applicable or phase not reached yet; "not met" blocks. Applies only to the "overall system" path (project type gesamtsystem or both) — L321: "The division into ''concept for the overall system'' and ''projects'' is an elementary basis."; without a project type (M8203-01) the check waits. "Phase not reached yet": phase goals are "results to be achieved after completion of the respective service phase" (§ 2.1); the assessment is the project team''s (L202). "Partially met" passes here but triggers the Projektstopp review REQ-06-2 (§ 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued.").'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-06' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-04' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-04'
   AND md5(cr.condition) = '0affd58587301285dcfc54bbcc92d843';

