   SET condition = 'IF project_type IN {''einzelprojekt'', ''both''} THEN ((pz_64_1_status == "erreicht" OR pz_64_1_status == "teilweise_erreicht" OR pz_64_1_status == "nicht_zutreffend" OR pz_64_1_status == "noch_nicht_erreicht") AND (pz_64_2_status == "erreicht" OR pz_64_2_status == "teilweise_erreicht" OR pz_64_2_status == "nicht_zutreffend" OR pz_64_2_status == "noch_nicht_erreicht") AND (pz_64_3_status == "erreicht" OR pz_64_3_status == "teilweise_erreicht" OR pz_64_3_status == "nicht_zutreffend" OR pz_64_3_status == "noch_nicht_erreicht") AND (pz_64_4_status == "erreicht" OR pz_64_4_status == "teilweise_erreicht" OR pz_64_4_status == "nicht_zutreffend" OR pz_64_4_status == "noch_nicht_erreicht") AND (pz_64_5_status == "erreicht" OR pz_64_5_status == "teilweise_erreicht" OR pz_64_5_status == "nicht_zutreffend" OR pz_64_5_status == "noch_nicht_erreicht") AND (pz_64_6_status == "erreicht" OR pz_64_6_status == "teilweise_erreicht" OR pz_64_6_status == "nicht_zutreffend" OR pz_64_6_status == "noch_nicht_erreicht") AND (pz_64_7_status == "erreicht" OR pz_64_7_status == "teilweise_erreicht" OR pz_64_7_status == "nicht_zutreffend" OR pz_64_7_status == "noch_nicht_erreicht") AND (pz_64_8_status == "erreicht" OR pz_64_8_status == "teilweise_erreicht" OR pz_64_8_status == "nicht_zutreffend" OR pz_64_8_status == "noch_nicht_erreicht") AND (pz_64_9_status == "erreicht" OR pz_64_9_status == "teilweise_erreicht" OR pz_64_9_status == "nicht_zutreffend" OR pz_64_9_status == "noch_nicht_erreicht") AND (pz_64_10_status == "erreicht" OR pz_64_10_status == "teilweise_erreicht" OR pz_64_10_status == "nicht_zutreffend" OR pz_64_10_status == "noch_nicht_erreicht") AND (pz_64_11_status == "erreicht" OR pz_64_11_status == "teilweise_erreicht" OR pz_64_11_status == "nicht_zutreffend" OR pz_64_11_status == "noch_nicht_erreicht") AND (pz_64_12_status == "erreicht" OR pz_64_12_status == "teilweise_erreicht" OR pz_64_12_status == "nicht_zutreffend" OR pz_64_12_status == "noch_nicht_erreicht"))',
       description = 'Alle Phasenziele von § 6.4 Ausführungsvorbereitung (Status je Ziel auf diesem Blatt). Bestanden: Erreicht, Teilweise erreicht, Nicht zutreffend oder Phase noch nicht erreicht; „Nicht erreicht“ blockiert. Gilt nur für den Pfad „Projekte“ (Projekttyp Einzelprojekt oder Beides) — L321 (PDF S. 13): „Die Aufteilung in „Konzept für das Gesamtsystem“ und „Projekte“ ist dabei eine elementare Grundlage.“; ohne Projekttyp (M8203-01) wartet die Prüfung. „Phase noch nicht erreicht“: Phasenziele sind „Ergebnisse, die nach Abschluss der jeweiligen Leistungsphase zu erreichen sind“ (§ 2.1, PDF S. 10); die Bewertung liegt beim Projektteam (L202, PDF S. 9: „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“). „Teilweise erreicht“ besteht hier, löst aber die Projektstopp-Prüfung REQ-11-2 aus (§ 3, PDF S. 12: „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich.“).
[EN] All phase goals of § 6.4 preparation of execution (status per goal on this sheet). Pass: met, partially met, not applicable or phase not reached yet; "not met" blocks. Applies only to the "projects" path (project type einzelprojekt or both) — L321: "The division into ''concept for the overall system'' and ''projects'' is an elementary basis."; without a project type (M8203-01) the check waits. "Phase not reached yet": phase goals are "results to be achieved after completion of the respective service phase" (§ 2.1); the assessment is the project team''s (L202). "Partially met" passes here but triggers the Projektstopp review REQ-11-2 (§ 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued.").'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-11' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-14' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-14'
   AND md5(cr.condition) = '5b7cb97c373a439636d164d0800e7d7e';

