-- REQ-25 M8203-19
UPDATE compliance_requirements cr
   SET condition = 'IF digitale_methoden_bim_angewendet == true THEN (bim_project_definition_complete == true AND aia_available == true AND bap_defined == true AND cde_platform_defined == true)',
       description = '§ 7.2.2 Ziele (PDF S. 21): „Die BIM-Projektdefinition ist abgeschlossen.“ „Die AIA (Auftraggeberinformationsanforderungen) liegen vor.“ „Der BAP (BIM-Abwicklungsplan) ist definiert und abgestimmt.“ — nur wenn das Projekt mit digitaler Planung nach der BIM-Methodik abgewickelt wird (Frage auf diesem Blatt; § 7.2.1, PDF S. 21: „Die digitale Planung, hier insbesondere die BIM-Methodik, kristallisiert sich mehr und mehr als Arbeitsinstrument und Methode heraus.“).
[EN] § 7.2.2 goals: "The BIM project definition is completed." "The AIA (employer''s information requirements) are available." "The BAP (BIM execution plan) is defined and agreed." — only when the project is run with digital planning using the BIM method (question on this sheet; § 7.2.1: "Digital planning, here in particular the BIM method, is increasingly emerging as a working tool and method.").'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-25' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-19' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-19'
   AND md5(cr.condition) = 'e102b5ca0ff25be4fc8741b388f4b2ca';

-- REQ-26 M8203-19
UPDATE compliance_requirements cr
   SET condition = 'IF digitale_methoden_bim_angewendet == true THEN (digital_twin_after_project == true)',
       description = '§ 7.2.3 Ziele (PDF S. 22): „Die erarbeiteten digitalen Modelle werden für alle Belange der Planungsphasen und der Ausführungsphase, samt Inbetriebnahme durchgängig angewendet und gepflegt.“ „Das Bestandsmodell ist nach Abschluss des Projekts fertiggestellt („Digital Twin“).“ — nur bei digitaler Planung nach der BIM-Methodik (Frage auf diesem Blatt).
[EN] § 7.2.3 goals: "The digital models developed are applied and maintained consistently for all aspects of the planning phases and the execution phase, including commissioning." "The as-built model is completed after the end of the project (''digital twin'')." — only with digital planning using the BIM method (question on this sheet).'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-26' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-19' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-19'
   AND md5(cr.condition) = '067d64eaf428b0c70f846b5f52cab711';

-- REQ-27 M8203-19 → M8203-20
UPDATE compliance_requirements cr
   SET condition = 'bestandsdaten_complete_digital == true AND akz_in_place == true AND critical_infra_assessed == true',
       clause_reference = '§7.3',
       description = '§ 7.3 Ziele (PDF S. 22–23): „Bestandsdaten sind in Bezug auf die bevorstehenden Planungsaufgaben vollständig, aktuell und digital (bspw. georeferenziert, vektorisiert, Bezugssystem) verfügbar.“ · „Grundlage dafür ist ein eindeutiges Anlagenkennzeichnungssystem (AKZ).“ · „Die Anforderungen der Gesetzgebung zur kritischen Infrastruktur wurden im Vorfeld abgeklärt und sind im Projekt berücksichtigt.“ Liest die drei § 7.3-Fragen dieses Blatts (vorher leere Bedingung auf M8203-19).
[EN] § 7.3 goals: "Existing-asset data are complete, current and digitally available for the upcoming planning tasks (e.g. georeferenced, vectorised, reference system)." · "The basis for this is an unambiguous plant identification system (AKZ)." · "The legal requirements on critical infrastructure were clarified beforehand and are taken into account in the project." Reads the three § 7.3 questions of this sheet (was an empty condition on M8203-19).',
       worksheet_template_id = wt.id
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-27' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-19' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-20'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e';

-- REQ-29 M8203-19 → M8203-21
UPDATE compliance_requirements cr
   SET condition = 'IF digitale_methoden_bim_angewendet == true THEN (cde_used_for_communication == true AND bim_communication_interfaces == true)',
       clause_reference = '§7.5.2',
       description = '§ 7.5.2 (PDF S. 23): „Unter Projektkommunikation wird der Einsatz von Kommunikationsplattformen verstanden. Beim Einsatz der BIM-Planung stehen dafür Werkzeuge bereit und werden eingesetzt.“ Ziele: „Schnittstellen zwischen der rein digitalen Kommunikation (bspw. über das BIM-Modell) und der Kommunikation in Planungs- und Baubesprechungen sind geklärt.“ · „Eine CDE-BIM-Plattform als Kommunikationsplattform ist eingerichtet und wird genutzt.“ — nur bei digitaler Planung nach der BIM-Methodik (Frage auf M8203-19). Vorher leere Bedingung auf M8203-19.
[EN] § 7.5.2: "Project communication means the use of communication platforms. Where BIM planning is used, tools are available for this and are used." Goals: "Interfaces between purely digital communication (e.g. via the BIM model) and communication in planning and site meetings are clarified." · "A CDE-BIM platform is set up and used as the communication platform." — only with digital planning using the BIM method (question on M8203-19). Was an empty condition on M8203-19.',
       worksheet_template_id = wt.id
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-29' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-19' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-21'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e';

-- REQ-30 M8203-19 → M8203-21
UPDATE compliance_requirements cr
   SET condition = 'public_info_via_digital_media == true AND communication_concept_adaptive == true',
       clause_reference = '§7.5.3',
       description = '§ 7.5.3 Ziele (PDF S. 23–24): „Betroffene erhalten über geeignete digitale Medien (bspw. Projektwebsite) Zugang zu den für sie wichtigen Informationen.“ · „Ein Kommunikationskonzept ist erarbeitet, welches nicht starr ist, sondern sich dem Projektverlauf anpasst und an den Projektphasen des Projekts orientiert.“ Vorher las das Gate das Feld von REQ-26 (Digital Twin, § 7.2.3) auf M8203-19.
[EN] § 7.5.3 goals: "Affected parties get access to the information important to them through suitable digital media (e.g. a project website)." · "A communication concept is drawn up that is not rigid but adapts to the course of the project and is oriented to its phases." Before, the gate read REQ-26''s field (digital twin, § 7.2.3) on M8203-19.',
       worksheet_template_id = wt.id
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-30' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-19' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-21'
   AND md5(cr.condition) = '067d64eaf428b0c70f846b5f52cab711';

-- REQ-02 M8203-01 → M8203-02
UPDATE compliance_requirements cr
   SET condition = 'anw_hinweis_1_confirmed == true AND anw_hinweis_2_confirmed == true AND anw_hinweis_3_confirmed == true AND anw_hinweis_4_confirmed == true',
       clause_reference = '§1 Anwendungshinweise',
       description = 'Die vier Anwendungshinweise (§ 1, PDF S. 9), z. B. „Im konkreten Projekt werden aus den Qualitätselementen die projektspezifischen Anforderungen und Aufgabenlisten, inklusive Zuständigkeiten, vom Anwendenden entwickelt und in Arbeitsunterlagen (beispielsweise Checklisten) dokumentiert.“ und „Eine Vervollständigung an den jeweiligen Projektaufgaben wird im Projektteam durchgeführt.“ — zur Kenntnis genommen (die vier Fragen dieses Blatts). Das Merkblatt druckt Hinweise, keine Pflicht zur Kenntnisnahme: Warnung, keine Blockade. Vorher leere Bedingung auf M8203-01.
[EN] The four application notes (§ 1), e.g. "In the specific project the user develops the project-specific requirements and task lists, including responsibilities, from the quality elements and documents them in working papers (e.g. checklists)." and "Completion for the respective project tasks is carried out in the project team." — acknowledged (the four questions of this sheet). The Merkblatt prints notes, not a duty to acknowledge: warning, no block. Was an empty condition on M8203-01.',
       worksheet_template_id = wt.id
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-02' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-01' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-02'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e';

-- REQ-03 M8203-01 → M8203-03
UPDATE compliance_requirements cr
   SET condition = 'phase_definition_acknowledged == true AND phasenziele_definition_acknowledged == true AND projektziele_definition_acknowledged == true AND qe_definition_acknowledged == true',
       clause_reference = '§2.1',
       description = '§ 2.1 Definitionen (PDF S. 10): „Die Begriffe, die im Abschnitt 3 des Merkblatts DWA-M 820-1:2020 und Abschnitt 2 des Merkblatts DWA-M 820-2:2023 enthalten sind, gelten inhaltlich unverändert auch in diesem dritten Teil.“ — die vier Begriffe Phase, Phasenziele, Projektziele, Qualitätselemente zur Kenntnis genommen (die vier Fragen dieses Blatts). Keine gedruckte Pflicht: Warnung. Vorher leere Bedingung auf M8203-01.
[EN] § 2.1 definitions: "The terms contained in section 3 of DWA-M 820-1:2020 and section 2 of DWA-M 820-2:2023 apply unchanged in content in this third part as well." — the four terms phase, phase goals, project goals, quality elements acknowledged (the four questions of this sheet). No printed duty: warning. Was an empty condition on M8203-01.',
       worksheet_template_id = wt.id
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-03' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-01' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-03'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e';

-- REQ-05 M8203-04 → M8203-02
UPDATE compliance_requirements cr
   SET condition = 'IF kleiner_kommunaler_betrieb == true THEN (grundsatz_two_step_followed == true)',
       clause_reference = '§3',
       description = '§ 3 (PDF S. 12): „Kleinere kommunale Betriebe haben die Möglichkeit, sich durch externe Fachexpertise unterstützen zu lassen. Hier ist die Zweistufigkeit erforderlich; d. h. zunächst eine Gesamtsystembetrachtung, inklusive Abwägung der Wirtschaftlichkeit, zu erstellen und erst dann Einzelprojekte zu definieren, die den langfristigen Bedarf auch wirklich decken.“ Gilt nur, wenn der Auftraggeber ein kleinerer kommunaler Betrieb ist (Frage auf diesem Blatt). Schweregrad Warnung unverändert — das gedruckte „erforderlich“ spräche für eine Blockade (Freigabe-Entscheidung, Sign-off). Vorher leere Bedingung auf M8203-04.
[EN] § 3: "Smaller municipal operators may draw on external expertise. Here the two-stage approach is required, i.e. first an overall-system review including a weighing of economic efficiency, and only then the definition of single projects that really meet the long-term demand." Applies only when the client is a smaller municipal operator (question on this sheet). Severity warning unchanged — the printed "erforderlich" (required) would support a block (owner''s sign-off). Was an empty condition on M8203-04.',
       title_de = 'Zweistufigkeit bei kleineren kommunalen Betrieben (§ 3)',
       title_en = 'Two-stage approach for smaller municipal operators (§ 3)',
       worksheet_template_id = wt.id
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-05' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-04' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-02'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e';

-- REQ-31 M8203-22 → M8203-24
UPDATE compliance_requirements cr
   SET condition = 'IF projektstopp_code == 1 THEN (projektstopp_review_triggered == true)',
       clause_reference = '§3',
       description = '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Gesamtsicht auf M8203-24: ist der berechnete Projektstopp-Code 1 (mindestens ein Phasenziel „Nicht erreicht“ oder „Teilweise erreicht“; „Phase noch nicht erreicht“ zählt nicht), muss „Projektstopp-Prüfung ausgelöst“ (M8203-02) bejaht sein. Die blockierenden Prüfungen je Phase sind REQ-06-2 … REQ-14-2. Vorher leere Bedingung auf M8203-22.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Overall view on M8203-24: when the computed Projektstopp code is 1 (at least one phase goal "not met" or "partially met"; "phase not reached yet" does not count), "Projektstopp review triggered" (M8203-02) must be Yes. The blocking per-phase checks are REQ-06-2 … REQ-14-2. Was an empty condition on M8203-22.',
       worksheet_template_id = wt.id
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id, worksheet_templates wt
 WHERE cr.code = 'REQ-31' AND w.id = cr.worksheet_template_id AND w.code = 'M8203-22' AND s.code = 'DWA-M-820-3'
   AND wt.standard_id = s.id AND wt.code = 'M8203-24'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e';

-- 4. NEW block gates REQ-06-2 … REQ-14-2 (S-03, sign-off: new-gate ruling)
-- REQ-06-2 (M8203-04, NEW block gate — sign-off)
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, description, clause_reference, severity)
SELECT w.id, 'REQ-06-2', 'Projektstopp-Prüfung und Risikoanalyse bei nicht oder nur teilweise erreichten Phasenzielen (§ 5.2 Bedarfsplanung Konzept)', 'Projektstopp review and risk analysis when phase goals are not or only partially met (§ 5.2 needs planning (concept))', 'IF pz_52_1_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_52_2_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_52_3_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_52_4_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_52_5_status IN {''nicht_erreicht'', ''teilweise_erreicht''} THEN (pz_52_projektstopp_risikoanalyse == true)',
       '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Modalverben „ist … erforderlich“ / „muss“ → Blockade. Ist ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ („nur unvollständig erreicht“), muss „Projektstopp-Prüfung mit Risikoanalyse durchgeführt“ (dieses Blatt) bejaht sein. „Phase noch nicht erreicht“ und „Nicht zutreffend“ lösen nichts aus.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Modal verbs "ist … erforderlich" (is required) / "muss" (must) → block. When a phase goal of this sheet is "not met" or "partially met" ("only incompletely achieved"), "Projektstopp review with risk analysis carried out" (this sheet) must be Yes. "Phase not reached yet" and "not applicable" trigger nothing.',
       '§3', 'block'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE s.code = 'DWA-M-820-3' AND w.code = 'M8203-04'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements c2 WHERE c2.worksheet_template_id = w.id AND c2.code = 'REQ-06-2');

