-- REQ-11-2 (M8203-14, NEW block gate — sign-off)
INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, title_en, condition, description, clause_reference, severity)
SELECT w.id, 'REQ-11-2', 'Projektstopp-Prüfung und Risikoanalyse bei nicht oder nur teilweise erreichten Phasenzielen (§ 6.4 Ausführungsvorbereitung)', 'Projektstopp review and risk analysis when phase goals are not or only partially met (§ 6.4 preparation of execution)', 'IF pz_64_1_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_2_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_3_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_4_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_5_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_6_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_7_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_8_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_9_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_10_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_11_status IN {''nicht_erreicht'', ''teilweise_erreicht''} OR pz_64_12_status IN {''nicht_erreicht'', ''teilweise_erreicht''} THEN (pz_64_projektstopp_risikoanalyse == true)',
       '§ 3 (PDF S. 12): „Werden Phasenziele nicht oder nur unvollständig erreicht, ist die Prüfung eines Projektstopps erforderlich. Im Rahmen einer Risikoanalyse muss bewertet werden, ob und wie das Projekt fortgeführt werden kann.“ Modalverben „ist … erforderlich“ / „muss“ → Blockade. Ist ein Phasenziel dieses Blatts „Nicht erreicht“ oder „Teilweise erreicht“ („nur unvollständig erreicht“), muss „Projektstopp-Prüfung mit Risikoanalyse durchgeführt“ (dieses Blatt) bejaht sein. „Phase noch nicht erreicht“ und „Nicht zutreffend“ lösen nichts aus.
[EN] § 3: "If phase goals are not or only incompletely achieved, a Projektstopp review is required. A risk analysis must assess whether and how the project can be continued." Modal verbs "ist … erforderlich" (is required) / "muss" (must) → block. When a phase goal of this sheet is "not met" or "partially met" ("only incompletely achieved"), "Projektstopp review with risk analysis carried out" (this sheet) must be Yes. "Phase not reached yet" and "not applicable" trigger nothing.',
       '§3', 'block'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE s.code = 'DWA-M-820-3' AND w.code = 'M8203-14'
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements c2 WHERE c2.worksheet_template_id = w.id AND c2.code = 'REQ-11-2');

