-- 5. S-02 path routing: every section of the Gesamtsystem sheets (M8203-04 … -10, -22) and of the Projekt sheets (M8203-11 … -18, -23)
--    (only where no rule exists — the 2026-10-05 dump has none; the Plan-3 staged blocks m820_3-C-2 / C-3, same text)
UPDATE worksheet_sections ws
   SET visible_when = 'project_type IN {''gesamtsystem'', ''both''}'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE ws.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND ws.visible_when IS NULL
   AND w.code IN ('M8203-04', 'M8203-05', 'M8203-06', 'M8203-07', 'M8203-08', 'M8203-09', 'M8203-10', 'M8203-22');
UPDATE worksheet_sections ws
   SET visible_when = 'project_type IN {''einzelprojekt'', ''both''}'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE ws.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND ws.visible_when IS NULL
   AND w.code IN ('M8203-11', 'M8203-12', 'M8203-13', 'M8203-14', 'M8203-15', 'M8203-16', 'M8203-17', 'M8203-18', 'M8203-23');

-- 6. S-02 consumer reach (supersedes the Plan-3 staged block m820_3-C-1, option a): project_type '{ALL}' → the 17 sheets that carry a
--    project_type rule ('ALL' equals no worksheet code, so loadInheritedFields never handed project_type to any sheet)
UPDATE fields f
   SET consumer_worksheets = ARRAY['M8203-04', 'M8203-05', 'M8203-06', 'M8203-07', 'M8203-08', 'M8203-09', 'M8203-10', 'M8203-11', 'M8203-12', 'M8203-13', 'M8203-14', 'M8203-15', 'M8203-16', 'M8203-17', 'M8203-18', 'M8203-22', 'M8203-23']::text[]
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND f.symbol = 'project_type'
   AND f.consumer_worksheets = ARRAY['ALL']::text[];

-- 7. visible_when on existing fields (plain rule; only where none exists — the dump has none): S-14 two-stage question only for a
--    smaller municipal operator; S-07 the seven BIM questions only when the BIM method is used
UPDATE fields f
   SET visible_when = 'kleiner_kommunaler_betrieb == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND f.symbol = 'grundsatz_two_step_followed' AND f.visible_when IS NULL;
UPDATE fields f
   SET visible_when = 'digitale_methoden_bim_angewendet == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND f.symbol = 'aia_available' AND f.visible_when IS NULL;
UPDATE fields f
   SET visible_when = 'digitale_methoden_bim_angewendet == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND f.symbol = 'bap_defined' AND f.visible_when IS NULL;
UPDATE fields f
   SET visible_when = 'digitale_methoden_bim_angewendet == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND f.symbol = 'bim_project_definition_complete' AND f.visible_when IS NULL;
UPDATE fields f
   SET visible_when = 'digitale_methoden_bim_angewendet == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND f.symbol = 'cde_platform_defined' AND f.visible_when IS NULL;
UPDATE fields f
   SET visible_when = 'digitale_methoden_bim_angewendet == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-19' AND f.symbol = 'digital_twin_after_project' AND f.visible_when IS NULL;
UPDATE fields f
   SET visible_when = 'digitale_methoden_bim_angewendet == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND f.symbol = 'bim_communication_interfaces' AND f.visible_when IS NULL;
UPDATE fields f
   SET visible_when = 'digitale_methoden_bim_angewendet == true'
  FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id
 WHERE f.worksheet_template_id = w.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-21' AND f.symbol = 'cde_used_for_communication' AND f.visible_when IS NULL;

COMMIT;
